/* Spanish POS proposal narration. Each cue has an explicit visual target; no text is
 * derived from presenter instructions, source code, or infrastructure logs.
 * Lab indexes are zero-based and match pos-reveal-labs.js. All examples are
 * synthetic; the script explains a proposal, not an implemented backend.
 */
(() => {
  'use strict';
  const content = {};
  const cue = (text, selector) => ({ text, ...(selector ? { focus: { selector } } : {}) });
  const node = (text, nodes, edges = []) => ({ text, focus: { nodes, edges } });
  function add(id, cues) {
    if (content[id]) throw new Error(`Duplicate narration: ${id}`);
    content[id] = cues.map((item, index) => ({ id: `${id}-${String(index + 1).padStart(2, '0')}`, ...item }));
  }
  function cards(id, opening, paragraphs, ending) {
    add(id, [cue(opening, '.slide-head'), ...paragraphs.map((text, index) => cue(text, `.concept-card:nth-child(${index + 1})`)), ...(ending ? [cue(ending, '.takeaway')] : [])]);
  }
  function compare(id, opening, paragraphs, ending) {
    add(id, [cue(opening, '.slide-head'), ...paragraphs.map((text, index) => cue(text, `.compare-column:nth-child(${index + 1})`)), ...(ending ? [cue(ending, '.takeaway')] : [])]);
  }

  add('un-producto-varios-paises', [
    cue('Proponemos POS Platform como producto corporativo para Chile, Perú y España, con un núcleo común que permita incorporar países sin reconstruir el sistema. La continuidad sin Internet es un requisito junto con integridad financiera, permisos, experiencia común, extensibilidad y recuperación operativa.', '.slide-head'),
    cue('El núcleo compartido concentra ventas, turnos, caja, devoluciones, precios y contratos de integración. Una mejora de una regla común se distribuye como parte del producto y conserva sus pruebas entre perfiles nacionales.', '.cover-unit:nth-child(1)'),
    cue('Cada perfil nacional selecciona moneda, entidad, módulos, permisos y proveedores ya homologados. La configuración está versionada y se conserva localmente. Un proveedor nuevo o una regla distinta requiere implementar y validar su extensión antes de habilitarla.', '.cover-unit:nth-child(3)'),
    cue('Las diferencias fiscales, de pago, ERP y dispositivos se implementan detrás de contratos propios del POS. Esa separación permite sustituir proveedores manteniendo los casos de negocio. La propuesta requiere construir y validar esas capacidades; la maqueta no acredita su implementación productiva.', '.cover-unit:nth-child(5)')
  ]);
  add('ruta-de-aprendizaje', [
    cue('La propuesta conecta operación de tienda, plataforma de país y evolución del producto. Una venta se confirma en sucursal; su entrega a país y su integración con el ERP continúan con estados y evidencia independientes.', '.slide-head'),
    cue('El cliente Angular con Tauri utiliza el backend de sucursal por la red local. Recomendamos NestJS con Fastify y PostgreSQL, compartidos por las cajas de la tienda. Esa ubicación permite mantener operaciones autorizadas durante una caída de Internet.', '.route-entry:nth-child(1)'),
    cue('La sucursal calcula precios y ofertas con una versión local aprobada. La venta conserva esa versión, el importe y la explicación. Una actualización se prepara y valida fuera de los datos activos antes de publicarse.', '.route-entry:nth-child(3)'),
    cue('Los sincronizadores entregan operaciones pendientes y reciben maestros, precios y configuración. La plataforma de país consolida registros e integra con los proveedores. Cada destino conserva identidad, progreso y causas de fallo para recuperar sin duplicar efectos.', '.route-entry:nth-child(5)'),
    cue('El monorepo Nx organiza aplicaciones, módulos de negocio y adaptadores. La entrega del producto se gobierna mediante contratos versionados, combinaciones homologadas y despliegue gradual. El piloto debe demostrar reutilización entre países y recuperación operativa.', '.route-entry:nth-child(7)')
  ]);
  cards('objetivos-del-producto', 'POS Platform debe cubrir cinco capacidades conjuntas: reutilización entre países, integridad del dinero, experiencia común, control de acceso y continuidad recuperable. El piloto validará esas capacidades con operaciones y fallos representativos.', [
    'Ventas, caja y devoluciones comparten implementación y pruebas entre países. La incorporación de un segundo perfil debe identificar qué contratos se reutilizan, qué configuración cambia y qué extensiones nuevas necesita.',
    'Cada importe se vincula con una venta, un intento de pago y los documentos correspondientes. Los reenvíos mantienen identidad y contenido. Si falta una respuesta del proveedor, el resultado permanece incierto hasta obtener evidencia.',
    'Experiencia y control incluyen una interfaz coherente, permisos comprobados y responsables de cada módulo. Ocultar un botón no basta para autorizar una operación: esa comprobación también pertenece al backend.',
    'La operación controla vigencias, recuperación y compatibilidad de la flota. Los despliegues necesitan pruebas de restauración, versiones mixtas y modalidades nacionales, además de las comprobaciones funcionales de venta.'
  ]);
  compare('compartir-configurar-extender', 'Proponemos separar el producto en núcleo común, perfiles aprobados y extensiones. Las reglas compartidas permanecen en los módulos del POS; las diferencias nacionales se ubican en configuración compatible o en implementaciones con contratos y pruebas propios.', [
    'El núcleo común contiene reglas e identidades compartidas. Por ejemplo, una venta necesita un importe con moneda y un ciclo de confirmación comprensible. Sus pruebas de regresión deben seguir pasando al incorporar una variante nacional.',
    'El perfil aprobado combina capacidades ya soportadas. Selecciona país, entidad, permisos y proveedores compatibles. Antes de activarlo se valida la combinación; una excepción de caja no puede ampliar libremente permisos de crédito o fiscalidad.',
    'La extensión implementa una diferencia legítima: una política nacional o el protocolo de un proveedor nuevo. Requiere contrato, pruebas y homologación. Si el contrato común no alcanza, puede evolucionar de forma controlada para todo el producto.'
  ], 'Cada diferencia tiene un módulo responsable, una configuración versionada o un adaptador homologado. El producto mantiene una evolución común y evita repositorios nacionales que acumulen reglas incompatibles.');
  cards('recorrido-del-negocio', 'La operación propuesta prepara la caja, cotiza y cobra, confirma la venta y después integra y concilia. Cada etapa tiene autorización, estado y evidencia propios para identificar qué está terminado y quién debe resolver lo pendiente.', [
    'Antes de operar, la caja abre turno y comprueba permisos, datos vigentes y capacidades disponibles. El backend valida ese contexto antes de autorizar la venta; una opción visible en la pantalla no sustituye la comprobación.',
    'Cotizar y cobrar son decisiones relacionadas, pero distintas. El cálculo utiliza una versión conocida. El intento de pago conserva identidad y un resultado que puede ser aprobado, rechazado o todavía desconocido.',
    'Confirmar conserva la venta y su evidencia local. La documentación se realiza según el régimen y proveedor homologados. No estamos suponiendo una transacción única entre la base, un banco y un emisor fiscal.',
    'Integrar lleva el hecho a país y al ERP; conciliar compara resultados y resuelve diferencias. Que el ERP esté pendiente no significa que debamos volver a cobrar la venta ya realizada.'
  ], 'Relacionamos venta, pago, documento y contabilidad mediante referencias, manteniendo sus estados propios.');
  compare('estado-de-las-decisiones', 'La dirección de cliente Angular con Tauri y la organización con Nx están indicadas. NestJS con Fastify, PostgreSQL en sucursal y país, y la topología operativa son recomendaciones que deben validarse y aprobarse con el piloto.', [
    'El producto utilizará una interfaz común para web y escritorio y un repositorio con módulos compartidos. El perfil nacional seleccionará capacidades compatibles sin duplicar el núcleo de venta.',
    'Recomendamos confirmar la venta en PostgreSQL de sucursal y entregar después hacia país. NestJS con Fastify organiza el backend modular. La integración con ERP se ejecuta mediante workers supervisados y estados durables.',
    'Quedan por validar los contratos nacionales, los proveedores y la capacidad operativa. También debemos probar restauraciones y aprobar el piloto. Los nombres de tecnologías y los datos de las animaciones no acreditan rendimiento ni cumplimiento real.'
  ], 'La aprobación requiere contratos nacionales, inventario de proveedores, pruebas de recuperación y capacidad operativa. Los resultados del piloto deben cerrar la topología, el dimensionamiento y los compromisos antes del despliegue productivo.');

  add('contexto-del-pos', [
    cue('El POS concentra la operación de tiendas y se conecta con fuentes de maestros, pagos, fiscalidad y ERP. Cajeros, supervisores y equipo corporativo acceden con responsabilidades y permisos separados.', '.slide-head'),
    node('A la izquierda están las personas de tienda. El cajero opera y el supervisor autoriza o revisa. La relación vender y operar llega al POS. El sistema debe ofrecer capacidades distintas según la responsabilidad, en lugar de un permiso administrador para todo.', ['operator','pos'], ['operator-pos']),
    node('El equipo corporativo configura y opera la plataforma. Aprueba perfiles, versiones y combinaciones de proveedores, y mantiene seguimiento de entregas, conciliación y recuperación. Esas capacidades tienen permisos separados de la operación de caja.', ['platform','pos'], ['platform-pos']),
    node('A la derecha, maestros y precios publican datos autorizados. La flecha entra al POS. Guardar una copia local no convierte a la sucursal en autora de precios; necesitamos saber quién publica cada atributo y bajo qué contrato.', ['master','pos'], ['master-pos']),
    node('La relación con pago y fiscalidad solicita capacidades externas. Una respuesta debe acreditar un estado definido por su contrato. La confirmación de un proveedor no demuestra por sí sola la liquidación del pago ni todos los estados fiscales.', ['pos','provider'], ['pos-provider']),
    node('La integración se dirige al sistema asignado a cada país y fase: AX en Chile, Gira en España y el sistema propio de Perú, según los antecedentes. Cada operación conserva su destino; interfaces y garantías de esos sistemas siguen pendientes de validación.', ['pos','erp'], ['pos-erp']),
    cue('El POS concentra la operación de tienda y se relaciona con fuentes de datos y proveedores externos. Cada relación necesita un contrato que defina capacidades, autoridad de los datos y resultados posibles.', '.takeaway')
  ]);
  compare('modulos-antes-que-servidores', 'Recomendamos un backend modular por sucursal para coordinar venta, caja y precios con una transacción local. La separación inicial de procesos corresponde al trabajo de sincronización e integración, que puede progresar sin mantener abierta la interfaz.', [
    'Ventas, caja y precios mantienen contratos y propiedad de datos dentro del backend de sucursal. Se despliegan juntos y pueden coordinar sus cambios locales. La recuperación del proceso debe contemplar que su caída afecta a esos módulos.',
    'Recomendamos PostgreSQL por las relaciones y restricciones entre ventas, dinero, documentos e identidades, y por la transacción de negocio y outbox. Cada módulo controla sus tablas y migraciones. País mantiene una base operativa separada. MongoDB admite transacciones, pero no aporta una ventaja identificada que justifique otra persistencia en este alcance.',
    'Durante una caída de Internet, la venta autorizada continúa y la entrega a país queda pendiente. La pérdida de LAN o del servidor puede detener las cajas. Por eso la propuesta requiere respaldo, restauración y aislamiento del escritor anterior, con objetivos de recuperación acordados y ensayados.'
  ], 'Cada módulo controla sus tablas e interfaces. La unidad de trabajo coordina únicamente los cambios que deben confirmarse juntos. Compartir PostgreSQL no autoriza a integración ni sincronización a modificar libremente importes de venta.');
  add('contenedores-del-pos', [
    cue('La sucursal reúne cliente POS, backend, PostgreSQL y sincronizador. País mantiene su API, registro operativo y workers de integración. De izquierda a centro está la confirmación local; hacia país continúa la entrega, con una transacción independiente.', '.slide-head'),
    node('El cliente POS usa Angular y Tauri. Envía comandos al backend por la red local. La interfaz puede validar para ayudar al usuario, pero el backend vuelve a comprobar identidad, permisos y datos que protegen la venta.', ['ui','api'], ['ui-api']),
    node('El backend NestJS con Fastify confirma en PostgreSQL de sucursal. Allí conserva ventas, precios autorizados y outbox. PostgreSQL permite agrupar venta, movimiento y pendiente de entrega en una transacción; ese commit no acredita un asiento en el ERP.', ['api','db'], ['api-db']),
    node('El sincronizador consulta trabajo durable. Es un proceso supervisado separado de la ventana POS. Sus permisos son acotados: no se transforma en una vía libre para modificar dinero con cualquier sentencia SQL.', ['db','sync'], ['db-sync']),
    node('Cuando existe conectividad, el sincronizador entrega lotes por HTTPS a la API de país. Las identidades sobreviven a los reintentos. Si la respuesta se pierde, consultamos o reenviamos según el contrato; no inventamos otra venta.', ['sync','country'], ['sync-country']),
    node('La API de país confirma inbox, efecto local y siguiente trabajo en su PostgreSQL antes del acuse de aplicación. Esta es otra transacción. La sucursal sigue siendo autora de su venta; las dos bases no son escritores libres de la misma operación.', ['country','country-db'], ['country-country-db']),
    node('Los workers de país ejecutan después integración y publicación. Un acuse de país no dice que todos esos trabajos terminaron. Esta separación nos permite mostrar estados precisos: confirmado local, recibido en país e integración pendiente.', ['country-db','workers'], ['country-db-workers']),
    cue('La autoridad de venta está en sucursal. La interfaz pide, el backend aplica reglas, la base conserva y los procesos de entrega mantienen su propio progreso.', '.takeaway')
  ]);
  add('lugares-de-ejecucion', [
    cue('Cada puesto ejecuta Angular con Tauri y accede por LAN al servidor de sucursal. El servidor aloja el backend y PostgreSQL. La plataforma de país se comunica por la red externa. El perfil inicial permite perder Internet con LAN y servidor disponibles.', '.slide-head'),
    node('El puesto tiene cliente, lector e impresión. Accede al servidor por la red local, o LAN. Un puente nativo autorizado puede hablar con un periférico, pero no debe inventar otro importe ni otro intento de cobro.', ['register','branch'], ['register-branch']),
    node('El servidor de sucursal aloja backend y PostgreSQL. Es la autoridad local para este perfil. Si se pierde ese servidor o la LAN, no abrimos automáticamente una base independiente en cada caja: necesitaríamos otro diseño de propiedad y recuperación.', ['branch']),
    node('La conexión hacia país cruza la red externa, o WAN. Esa conexión puede interrumpirse mientras las operaciones permitidas continúan localmente. Permisos, precios y modalidades de pago siguen teniendo límites de vigencia y autorización.', ['branch','country'], ['branch-country']),
    node('El worker de sucursal funciona como proceso supervisado, independiente de la ventana POS. Conserva pendientes y progreso en almacenamiento durable. Su operación requiere comprobar estado, reiniciar ante fallos y recuperar entregas sin crear nuevas ventas.', ['branch','sync'], ['branch-sync']),
    node('La plataforma de país accede a la red autorizada del ERP mediante adaptadores homologados. Puede alojarse en cloud aprobado o en un centro de datos; el destino definitivo, la capacidad y los objetivos de recuperación deben acordarse.', ['country','erp'], ['country-erp'])
  ]);
  compare('limites-de-continuidad', 'La autonomía inicial del POS cubre pérdida de Internet con sucursal disponible. Cada operación sigue condicionada por vigencia de datos y permisos, disco, reloj, capacidad fiscal y modalidad de pago autorizada.', [
    'Sin Internet todavía podemos tener backend y PostgreSQL locales. Si precios, permisos y modalidades siguen válidos, ciertas ventas continúan y la entrega a país queda pendiente. La caída de red no renueva vigencias.',
    'Sin LAN o sin servidor se pierde acceso al escritor de este perfil. Debemos detener nuevas ventas afectadas y recuperar la autoridad. Crear otro escritor por caja sin protocolo podría generar historias incompatibles.',
    'Si falla un proveedor, depende de la capacidad homologada. No podemos asumir tarjeta offline ni documentación fiscal de contingencia universal. La interfaz debe comunicar la restricción concreta y la acción posible.'
  ], 'Copiar un cupón compartido no permite garantizar su uso único entre sucursales aisladas. Esa capacidad necesita conexión, derechos exclusivos asignados o una restricción aprobada.');
  add('backend-modular', [
    cue('El backend de sucursal concentra autorización, casos de venta y caja, motor de precios, contratos de proveedores y persistencia. Recomendamos NestJS con Fastify, manteniendo esos componentes dentro de una aplicación con fronteras de datos explícitas.', '.slide-head'),
    node('La entrada autorizada comprueba identidad, puesto, sucursal y capacidad de la operación. Después llama al caso de uso correspondiente. Ocultar una opción en la interfaz nunca reemplaza estas comprobaciones.', ['entry','usecase'], ['entry-usecase']),
    node('La aplicación coordina venta, caja o devolución. Cuando necesita calcular, consulta las reglas de precios con una versión local validada. Separar el cálculo permite probarlo con entradas conocidas sin depender de la pantalla.', ['usecase','pricing'], ['usecase-pricing']),
    node('Los contratos POS expresan capacidades de pago y fiscalidad. El caso de uso trabaja con esos acuerdos y con resultados reales. Una llamada externa no queda incluida en el commit SQL por estar iniciada desde este mismo backend.', ['usecase','ports'], ['usecase-ports']),
    node('Persistencia guarda cambios locales que deben quedar juntos: venta, movimientos, auditoría y outbox según la operación. La transacción no debe permanecer abierta mientras esperamos a un banco o al ERP.', ['usecase','store'], ['usecase-store']),
    cue('Ventas, caja y precios mantienen reglas, tablas e interfaces públicas propias. Las pruebas deben proteger esos límites y sus transacciones. Extraer un servicio requerirá demostrar el beneficio y resolver los nuevos fallos de comunicación.', '.takeaway')
  ]);

  compare('idempotencia-desde-cero', 'El contrato de recuperación del POS conserva la misma identidad y contenido al reenviar una operación. La recepción en país reconoce el resultado ya confirmado y evita repetir su efecto local, incluso si el acuse anterior se perdió.', [
    'Conservamos la identidad de la venta y del evento, junto con el mismo contenido. El receptor puede reconocer el intento y recuperar el resultado anterior. Ese reconocimiento necesita almacenamiento durable y una protección contra concurrencia.',
    'Un identificador nuevo parece una operación diferente. Puede generar otro registro o cobro. Una corrección legítima necesita una operación relacionada y autorizada, en lugar de reutilizar un ID con datos cambiados.',
    'La inbox de país utiliza una clave única por origen, consumidor e identificador de evento. Confirma deduplicación, efecto local y trabajo posterior en la misma transacción. La retención debe cubrir reenvíos y restauración. Los efectos externos inciertos requieren consulta, idempotencia demostrada o conciliación del proveedor.'
  ], 'Una identidad reutilizada con otro contenido se rechaza como conflicto. Las restricciones de unicidad, la transacción y la retención de evidencia deben probarse con concurrencia, reenvíos y restauración.');
  add('commit-y-outbox', [
    cue('La confirmación propuesta guarda venta, movimientos, auditoría y evento pendiente en la misma transacción de PostgreSQL. El pago se resuelve según su contrato antes de completar ese conjunto. La salida a país ocurre después del commit.', '.slide-head'),
    cue('Dentro de la transacción se confirma venta, movimiento de caja y auditoría. Todas reciben el mismo contexto transaccional. Si ese conjunto falla, ninguno de esos cambios locales queda confirmado por separado.', '.code-layout pre'),
    cue('También se añade el evento con una identidad estable. Guardarlo junto con la venta evita un hueco peligroso: tener una venta confirmada sin recordar que debe comunicarse. El worker lo publicará después del commit.', '.code-layout pre'),
    cue('La respuesta de confirmado se envía cuando la base terminó. Si el proceso cae antes de publicar, queda una fila recuperable. Si ya hubo un pago aprobado y falla esta escritura, se recupera desde la intención persistida; no se vuelve a cobrar a ciegas.', '.takeaway'),
    cue('La implementación deberá proteger autorización, restricciones y concurrencia, y conservar el identificador original del evento en cada reenvío. La prueba de recuperación debe detener el proceso entre el commit y la entrega para verificar que el pendiente sobrevive.', '.code-layout pre')
  ]);
  compare('pago-desconocido', 'Cuando el proveedor no responde a tiempo, el POS conserva el pago como desconocido. El cobro pudo completarse; la caja debe consultar la misma referencia o conciliar antes de permitir otro efecto monetario.', [
    'Si el proveedor acredita aprobación, guardamos su referencia y completamos el flujo permitido. Si falla la escritura local después, esa evidencia permite recuperar o realizar una resolución trazable según el contrato.',
    'Si acredita rechazo, conservamos la causa e informamos ese resultado. Un intento nuevo exige una decisión explícita. No confundimos una respuesta negativa confirmada con la simple ausencia de respuesta.',
    'Si el resultado es desconocido, mantenemos la identidad y consultamos o conciliamos. Cambiar de dispositivo o generar otro ID no borra el posible cobro anterior. La capacidad de consulta debe existir realmente en el proveedor.'
  ], 'Cada modalidad necesita un procedimiento para resultados desconocidos y una capacidad de consulta o conciliación homologada. La aplicación conserva la incertidumbre si el adquirente no permite resolverla automáticamente.');
  cards('autoridades-del-dinero', 'La propuesta mantiene cuatro resultados independientes: venta local, pago, documento fiscal y registro contable. Sus referencias se relacionan, pero cada estado requiere evidencia del sistema que lo controla.', [
    'La autoridad de la venta es el POS de origen. Conserva la operación confirmada y las correcciones trazables. Un rechazo posterior del ERP no hace desaparecer una compra realizada.',
    'El pago necesita evidencia del proveedor o del medio autorizado. Autorización y liquidación no son necesariamente el mismo estado. El POS conserva referencias sin sustituir a la autoridad que acredita ese dinero.',
    'El documento fiscal sigue el régimen y el emisor correspondiente. Aceptación, validez y contingencia no se deducen de que otro sistema haya recibido un evento de venta.',
    'La contabilidad tiene su propio ciclo de registro y contabilización. Relacionamos la operación ERP con la venta, pero no tratamos esos identificadores ni estados como si fueran uno solo.'
  ], 'Las diferencias se resuelven con anulaciones, devoluciones o ajustes auditables. No reescribimos silenciosamente la historia ni ofrecemos un reintentar genérico que pueda volver a cobrar.');

  compare('snapshot-y-delta-desde-cero', 'Proponemos dos canales complementarios para distribuir precios: eventos con cambios incrementales y cargas masivas programadas. Ambos preparan una versión aislada y pasan por la misma validación y activación local.', [
    'La carga masiva inicia o repara el espejo de la sucursal desde un corte consistente. Incluye todos los datos del ámbito y las bajas. El manifiesto identifica cobertura, versión y archivos para reanudar una descarga interrumpida.',
    'Los eventos distribuyen altas, cambios y eliminaciones desde una base compatible. Si falta una secuencia, la sucursal conserva lo recibido sin activarlo y recupera la cobertura faltante o solicita una carga completa.',
    'Los dos canales preparan una candidata separada de la versión activa. Se comprueban cobertura, referencias, reglas, compatibilidad y vigencia. La activación cambia el puntero y el checkpoint aplicado en una misma transacción; una descarga completa por sí sola no autoriza esa publicación.'
  ], 'Transportar menos datos no cambia la garantía de publicación. Las ventas nunca deberían leer una mezcla que todavía no fue validada como versión completa.');
  cards('espejo-de-precios', 'Proponemos un espejo autorizado de precios y ofertas en PostgreSQL de sucursal y un motor local compartido. La caja calcula con datos, reglas y versión conocidas, sin depender de una consulta remota de precios por cada venta.', [
    'Los datos autorizados incluyen listas, grupos y condiciones requeridas por las operaciones habilitadas. Primero hay que inventariar qué utiliza realmente el servicio actual; no asumir que una tabla de producto y precio es suficiente.',
    'Las ofertas tienen prioridades, acumulación, cantidades, fechas y redondeos. Para extraer el motor necesitamos casos de referencia. Comparar solo el total puede ocultar dos errores que se compensan entre sí.',
    'El manifiesto identifica versión, ámbito, procedencia y compatibilidad. También necesitamos un punto de continuidad para recuperar cambios. Guardar una copia sin estas referencias dificulta saber si sigue completa y autorizada.',
    'La evidencia del cálculo conserva importe, descuentos, reglas y versión junto a la operación. Esto permite responder por qué ese cliente recibió ese total, sin recalcular la historia usando el catálogo de hoy.'
  ], 'Cupones únicos o presupuestos compartidos requieren exclusión o restricciones propias. Tener sus datos copiados no garantiza consumo único entre tiendas desconectadas.');
  add('contrato-del-calculo', [
    cue('El motor de precios recibe cesta, contexto comercial, versión y tiempo autorizado. Devuelve importe, descuentos y reglas aplicadas. La misma entrada debe producir el mismo resultado en nodos homologados, con evidencia conservada en la operación.', '.slide-head'),
    cue('En la entrada hay una cesta con dos unidades, un grupo de cliente, una versión de precios y un tiempo de negocio autorizado. El motor no debería consultar arbitrariamente la hora del computador y cambiar una oferta según dónde lo ejecutamos.', '.code-layout pre'),
    cue('El ejemplo calcula dos productos de diez mil pesos y un descuento del diez por ciento: el total resulta dieciocho mil pesos. Devuelve también la regla aplicada y la versión. No guardamos solo el número; conservamos su explicación.', '.code-layout pre'),
    cue('El contrato financiero requiere moneda, escala, impuestos y política de redondeo definidos por país. El cálculo mostrado omite impuestos; el piloto debe incorporar las reglas reales y usar una representación de dinero que evite errores de decimales binarios.', '.takeaway'),
    cue('Las reglas de precios se ejecutan sin depender de Angular, SQL ni servicios remotos. Se validan con casos de referencia del sistema actual, comparando importes y explicación antes de publicar una nueva versión del motor.', '.code-layout pre')
  ]);
  compare('version-fijada', 'Cada cotización del POS fija la versión que produjo su importe. Una actualización de catálogo no modifica silenciosamente un ticket abierto. Al confirmar se revalida su vigencia y se aplica la política comercial acordada.', [
    'La venta en curso conserva la versión y las reglas que produjeron su total. Al confirmar se revalida según vigencia. Fijar una versión no equivale a permitir una oferta vencida para siempre.',
    'La versión nueva se prepara fuera de los datos activos. Cuando está completa y autorizada cambia el puntero de lectura. Las cotizaciones nuevas pueden usarla sin que la descarga haya reescrito las filas de la versión anterior.',
    'Las ventas históricas conservan sus importes y explicación. No se recalculan con precios actuales. Las versiones todavía referenciadas se retienen para cotizaciones, auditoría y recuperación; no se borran solo porque apareció otra.'
  ], 'Si una oferta vence antes del cobro, el negocio debe definir recotización o aceptación dentro de límites aprobados. La arquitectura conserva evidencia y hace cumplir esa decisión.');
  add('activacion-atomica', [
    cue('La activación del espejo usa un commit corto en PostgreSQL. La descarga y la validación se completan antes, fuera de la versión activa. La transacción publica únicamente una candidata completa, compatible y vigente.', '.slide-head'),
    cue('La primera operación prepara y valida la candidata. Todavía no cambia qué versión lee una venta. Separar esta etapa permite descargar, reanudar y comprobar cobertura sin bloquear la publicación actual.', '.code-layout pre'),
    cue('Dentro de la transacción se revalidan precondiciones y se activa solo si la versión actual coincide con la base esperada. Si otro trabajo publicó mientras tanto, la comparación falla. No sobrescribimos un avance más reciente.', '.code-layout pre'),
    cue('La inbox aplicada y el cursor avanzan en el mismo commit que el puntero. Los tres cambios quedan juntos o ninguno. De otro modo podríamos declarar progreso que la venta todavía no ve, o publicar sin recordar qué se aplicó.', '.code-layout pre'),
    cue('La publicación compara atómicamente la versión actual con la base esperada. Si no coincide, se reconstruye o revalida la candidata; no se fuerza el valor esperado. El piloto debe comprobar esta protección con publicaciones concurrentes.', '.takeaway')
  ]);
  compare('recibido-versus-aplicado', 'El panel de sincronización distinguirá recibido, validado y aplicado. La versión activa, el corte del origen, los cursores y la huella del manifiesto se conservan por separado para recuperar y explicar el progreso real.', [
    'Al recibir, la sucursal guarda porciones, identidad y progreso durable. Eso permite reanudar la descarga sin perder lo confirmado. El catálogo todavía no se publica si falta cobertura, compatibilidad o una referencia comercial.',
    'La validación comprueba la candidata completa. Su aprobación no cambia por sí sola la versión activa: todavía deben cumplirse las precondiciones y la vigencia al publicar.',
    'La aplicación se acredita cuando puntero activo, inbox aplicada y checkpoint quedan confirmados juntos. Las nuevas ventas leen entonces el conjunto publicado. Descargar archivos no adelanta ese cursor de aplicación.'
  ], 'La operación consultará versión comercial y progreso técnico como datos diferentes. Las alertas deben identificar si falta transferencia, validación o activación para que la recuperación actúe sobre la etapa correcta.');
  cards('fallos-de-precios', 'La recuperación del espejo mantiene la versión anterior íntegra mientras prepara la nueva, pero sólo permite usarla dentro de su vigencia. Cada fallo conserva causa, estado y una acción autorizada de recuperación.', [
    'Si la descarga está incompleta, conservamos progreso y reanudamos. La versión activa permanece íntegra. La existencia de algunas filas nuevas no significa que puedan utilizarse para vender.',
    'Si falta un evento, detenemos la publicación de ese ámbito y recuperamos cobertura. Saltar el hueco podría perder una baja o una condición comercial necesaria para interpretar el siguiente cambio.',
    'Si venció una promoción, aplicamos la política aprobada: podría permitir recotizar sin esa oferta o restringir la operación. No inventamos una solución universal ni renovamos su vida útil por no tener red.',
    'Si el reloj o disco son inválidos, restringimos la capacidad afectada y preservamos evidencia. Sin tiempo confiable no podemos alargar vigencias; sin espacio no podemos afirmar que una nueva venta quedó guardada.'
  ], 'Las pruebas deben cortar procesos antes y después de recibir, validar y activar, comprobando qué versión quedó visible y qué progreso sobrevivió.');
  cards('ejecucion-manual-programada', 'La propuesta habilita sincronización programada y ejecución manual mediante el mismo flujo. Ambas registran ámbito, autorización, exclusión, progreso y resultado, y aplican idénticas validaciones antes de publicar.', [
    'El calendario define zona horaria, frecuencia, ventana y fechas especiales. Programado no significa ejecutado exactamente a esa hora: capacidad y disponibilidad pueden retrasarlo. Hay que mostrar admisión prevista e inicio real.',
    'La ejecución manual conserva ámbito, motivo, usuario y resultado. El botón no omite validaciones ni inventa una excepción a una ventana cerrada. Cualquier excepción necesita una política y permiso explícitos.',
    'La exclusión evita dos publicadores incompatibles para el mismo ámbito. Un lease es una posesión temporal del trabajo; si el worker la pierde, las escrituras deben impedir que confirme como si siguiera siendo dueño.',
    'Los checkpoints permiten reanudar. Los límites de caudal protegen otros servicios. Reiniciar después de mantenimiento no debería borrar progreso ni activar automáticamente trabajo que debía permanecer detenido.'
  ], 'Usar el mismo proceso reduce diferencias peligrosas entre la sincronización automática, la recuperación y la acción manual del operador.');
  add('sincronizador-por-dentro', [
    cue('El sincronizador de sucursal conserva progreso, entrega operaciones confirmadas y activa datos autorizados. La fila superior contiene la salida hacia país; la inferior, la recepción, preparación y publicación de versiones locales.', '.slide-head'),
    node('La planificación o ejecución manual comprueba permiso, exclusión y auditoría. Decide cuándo admitir el trabajo sin cambiar sus garantías. El proceso también respeta mantenimiento, límites y capacidad disponible.', ['schedule']),
    node('La salida reclama operaciones ya confirmadas en outbox. Las entrega con identidad estable a país. No crea nuevas ventas ni asigna otro ID cada vez que se pierde una respuesta.', ['schedule','outbox','remote'], ['schedule-outbox','outbox-remote']),
    node('En sentido de entrada, país ofrece publicaciones versionadas. La recepción durable guarda snapshot, cambios y progreso antes de afirmar aplicación. Si el proceso reinicia, puede continuar desde la evidencia conservada.', ['remote','staging'], ['remote-staging']),
    node('La candidata se construye fuera de la versión activa. Debe quedar completa, compatible y autorizada. Este paso no se omite porque el cambio llegó por eventos ni porque lo solicitó manualmente un operador.', ['staging','validate'], ['staging-validate']),
    node('La publicación local cambia puntero y progreso aplicado en un commit corto. Solo entonces las lecturas nuevas utilizan la versión. Una descarga recibida no puede saltar directamente a activa sin pasar por validación.', ['validate','active'], ['validate-active']),
    cue('Los permisos del worker se limitan a su trabajo técnico y espejos autorizados. Una modificación que afecta dinero debe pasar por la responsabilidad del módulo, no por un job genérico con acceso a todo SQL.', '.takeaway')
  ]);
  cards('significado-de-acuses', 'El POS registrará confirmación local, recepción durable en país y resultado ERP como estados distintos. Cada acuse identifica su emisor, operación y alcance, evitando cerrar una obligación que todavía está pendiente en otro destino.', [
    'El commit de sucursal acredita que venta, movimientos y outbox quedaron confirmados en PostgreSQL. La venta existe localmente aunque su entrega a país siga pendiente. Ese resultado no confirma registros en otros sistemas.',
    'La API de país responde después de confirmar inbox, proyección y trabajo posterior en su PostgreSQL. Si la respuesta se pierde, la sucursal reenvía con identidad estable y país recupera el resultado previo.',
    'El resultado externo procede del ERP o proveedor. Su significado puede ser recibido, registrado o rechazado. Debemos conservar esa evidencia y distinguir un timeout de un rechazo explícito.',
    'La conciliación compara conteos, importes por moneda y referencias dentro de un ámbito. Es una comprobación distinta de tener una cola vacía o de recibir un acuse de transporte.'
  ], 'La interfaz debe nombrar destino y etapa. Recibido por país no significa contabilizado, aceptado fiscalmente ni liquidado.');
  compare('elegir-mensajeria', 'La recomendación base usa PostgreSQL, entrega durable por HTTPS y workers supervisados. BullMQ y RabbitMQ se evalúan como capacidades centrales adicionales según carga, distribución y soporte operativo; no se requieren brokers en cada caja.', [
    'Outbox e inbox transaccionales conservan intención y efecto local. Los lotes llevan identidades y progreso. Podemos validar estas garantías sin instalar un broker en cada sucursal.',
    'BullMQ es una opción para programar y recuperar trabajos centrales, como preparar publicaciones de precios. Redis coordina su ejecución; PostgreSQL conserva la operación y el resultado que deben sobrevivir a reintentos y limpieza de la cola.',
    'RabbitMQ es una opción para distribuir eventos a integración y analítica con colas independientes. Su adopción requiere validar topología, persistencia, confirmaciones, reintentos y cuarentena para cada destino.'
  ], 'Ninguna cola implementa las reglas de venta ni traduce el ERP. Si ya existe una capacidad corporativa compatible, debemos evaluar su reutilización antes de sumar otro producto para lo mismo.');

  add('fachada-e-interfaz-en-codigo', [
    cue('El worker de integración solicita registrar una venta mediante un contrato propio del POS. La fachada utiliza la implementación asignada al destino. Cambiar un proveedor no modifica esa solicitud ni reparte sus códigos por las pantallas.', '.slide-head'),
    cue('La interfaz superior declara registrar una venta POS y obtener un resultado POS. Esos tipos pertenecen a nuestro modelo, no son tablas del ERP ni la respuesta cruda de una biblioteca HTTP.', '.code-layout pre'),
    cue('La composición del backend suministra la implementación compatible con el contrato y el destino de la operación. Esa selección se prueba y se versiona; los consumidores siguen enviando datos del modelo POS.', '.code-layout pre'),
    cue('Integrar venta delega en la frontera asignada, que reúne traducción y comunicación con el proveedor. La aplicación debe conectar una implementación real y compatible en cada despliegue, conservando el destino de los pendientes.', '.code-layout pre'),
    cue('El flujo completo persistirá intención, autorización y destino antes de invocar al proveedor, y conservará su referencia y resultado. Ante una respuesta perdida, consultará o conciliará; la llamada no comparte una transacción con el ERP.', '.takeaway')
  ]);
  compare('acl-traduce-significado', 'Proponemos una ACL en cada integración ERP para traducir sus convenciones al modelo POS. Controlará identidades, dinero, tiempo y estados mediante equivalencias versionadas y pruebas por país y destino.', [
    'En dinero importa la unidad. Si el proveedor dice once mil cuatrocientos en pesos chilenos, no dividimos por cien solo por costumbre. La traducción debe conocer moneda, escala y representación antes de construir el valor propio.',
    'En tiempo conservamos el instante recibido y derivamos fecha comercial mediante una política explícita. Cortar los primeros caracteres de una fecha UTC no obtiene necesariamente la fecha local ni el día comercial de la sucursal.',
    'En estado, recibido para procesar no significa contabilizado. La ACL interpreta el código externo según su contrato y conserva referencia para seguimiento. Si no conoce una equivalencia, no puede declarar éxito para ocultar la diferencia.'
  ], 'La integración mantendrá un glosario del proveedor, casos de referencia y pruebas de equivalencia. Un código desconocido o una unidad incompatible debe producir una excepción visible, conservando la evidencia original.');
  add('acl-ejemplo-antes-despues', [
    cue('La respuesta externa se convierte a un resultado POS conservando importe, tiempo, estado y referencia. La transformación mostrada utiliza datos ficticios; las equivalencias reales deberán acordarse con cada proveedor.', '.slide-head'),
    cue('El dato de entrada usa importe textual, moneda, instante UTC y el código de recibido para procesar. Antes de traducir necesitamos saber qué significa cada campo. La apariencia del texto no define su unidad ni su calendario.', '.code-layout pre'),
    cue('La conversión de dinero valida unidad, moneda, escala y rangos; no cambia divisas ni divide automáticamente por cien. El instante se conserva y una política de calendario determina la fecha comercial.', '.code-layout pre'),
    cue('El estado conocido se traduce como recibido. Cualquier otro código, en esta muestra limitada, queda desconocido. El producto real debe cubrir los estados soportados y distinguir un dato inválido de un resultado remoto incierto.', '.code-layout pre'),
    cue('La salida es útil para el POS porque no exagera lo ocurrido. La evidencia original y la referencia externa se conservan en el flujo completo para consultar y explicar la operación después.', '.takeaway')
  ]);
  cards('contrato-pos-independiente', 'Los contratos de integración del POS expondrán capacidades de negocio propias: registrar operaciones y consultar sus resultados. Las tablas y códigos del ERP permanecen dentro de su adaptador y traducción.', [
    'Cada capacidad es concreta: registrar una venta, registrar un pago, consultar resultado o devolver. Nombres precisos evitan una operación genérica que oculte efectos diferentes detrás del mismo botón.',
    'La identidad incluye operación, entidad, país, destino y versión de contrato. Un reintento conserva identidad y contenido. Una corrección crea una operación relacionada que se puede auditar.',
    'Dinero y tiempo necesitan moneda, escala, instante y calendario. La fecha del hecho puede diferir de la fecha contable, especialmente con ventas atrasadas o periodos cerrados. Finanzas debe participar en esa regla.',
    'El resultado distingue aceptado, registrado, rechazado o desconocido según el contrato real. Un HTTP satisfactorio solo obtiene significado de negocio al interpretar qué operación se realizó y qué evidencia devolvió.'
  ], 'No extrapolamos convenciones de Chile a todos los países. Si el destino no ofrece unicidad y consulta fiable, hay que resolver esa limitación antes del piloto financiero.');
  compare('fachada-acl-adaptador', 'El módulo de integración separa una entrada estable para el worker, la traducción de significado y la comunicación técnica con el proveedor. Fachada, ACL y adaptador permanecen dentro de esa frontera, con contratos y pruebas diferenciados.', [
    'La fachada ofrece una capacidad estable: integrar una venta. Oculta coordinación interna y permite que el consumidor use lenguaje POS. No debe limitarse a reexponer todos los datos particulares del ERP con otro nombre.',
    'La ACL traduce significados: identidades de clientes, estados, unidades monetarias y fechas. Necesita equivalencias validadas. Pedido, venta, deuda y documento fiscal no son sinónimos porque se parezcan sus nombres.',
    'El adaptador ejecuta el protocolo: HTTP, WCF, SDK u otro. Conoce conexión y formatos técnicos, devuelve evidencia y errores tipados. No decide reglas de ofertas ni inventa éxito cuando la respuesta falta.'
  ], 'La política del flujo decide recuperación y reintentos. La ACL protege el modelo; la fachada simplifica el uso; el adaptador conversa con el proveedor.');
  add('codigo-frontera-erp', [
    cue('El worker registra una operación identificada a través de la fachada y conserva su resultado. Dentro de la integración, la ACL prepara la solicitud y traduce la respuesta; el adaptador usa el protocolo del destino asignado.', '.slide-head'),
    cue('La operación y su destino se persisten antes de llamar al ERP. El consumidor pide integrar mediante la fachada y guarda el resultado con la misma identidad, incluyendo la referencia externa necesaria para seguimiento.', '.code-layout pre'),
    cue('La función interna primero convierte la operación POS a una solicitud del destino. Después el adaptador realiza la llamada. Finalmente, la ACL convierte la evidencia externa a un resultado del contrato POS.', '.code-layout pre'),
    cue('Si el ERP aplica el efecto y se pierde la respuesta, el estado permanece desconocido. La recuperación consulta la referencia o utiliza idempotencia remota demostrada. La ausencia de respuesta no autoriza repetir ciegamente el efecto.', '.takeaway'),
    cue('Las referencias externas necesitan contexto: sistema, instancia, empresa y tipo de objeto. Un campo genérico de identificador externo no alcanza cuando conviven países, destinos o una migración de ERP.', '.code-layout pre')
  ]);
  cards('cambio-de-erp', 'La migración de ERP conservará el destino y las referencias históricas de cada operación. Un perfil nuevo sólo cambia el enrutamiento de operaciones nuevas; los pendientes e inciertos se recuperan contra su origen.', [
    'Primero preparamos contratos y equivalencias. Comparamos resultados con datos de referencia en lectura o simulación. No enviamos dos comandos reales de contabilización para comprobar si ambos sistemas coinciden.',
    'Después clasificamos pendientes: no enviados, confirmados, rechazados, inciertos y dependientes. Un resultado incierto no puede mudarse al sistema nuevo como si nunca hubiera llegado al anterior.',
    'El corte conserva destino y época. Una venta creada offline antes del cambio puede llegar después y mantener su contexto histórico. El momento de recepción no decide por sí solo dónde contabilizarla.',
    'Antes de retirar el adaptador anterior, resolvemos históricos y dependencias. Una devolución nueva puede referir una venta del ERP anterior; necesita referencias y tratamiento acordado, no recrear la factura a ciegas.'
  ], 'Revertir una configuración o un binario no deshace un asiento ya realizado. Migración ERP y evolución del POS son programas relacionados, con pruebas y responsabilidades propias.');
  compare('incorporar-pais', 'La incorporación de un segundo país debe reutilizar ventas, caja, auditoría y mecanismos durables, configurando lo compatible y desarrollando las diferencias fiscales, de pago y ERP. La combinación resultante se homologa antes de habilitarla.', [
    'Reutilizamos casos de venta y caja, identidades, auditoría y mecanismos durables donde sus reglas sean comunes. Las pruebas del núcleo siguen protegiendo ese comportamiento compartido.',
    'Configuramos entidad, moneda y formatos que el producto ya soporta, además de módulos, permisos y proveedores compatibles. Activar un nombre en un perfil no implementa un protocolo inexistente.',
    'Implementamos políticas nacionales faltantes y adaptadores nuevos. Después homologamos la combinación de núcleo, contrato, perfil, proveedor y dispositivo que corresponda. Los países nombrados no acreditan cumplimiento automático.'
  ], 'Si una regla nueva exige evolucionar el contrato común, podemos hacerlo de manera controlada. El objetivo es evitar forks y mantener una evolución compartida, no prohibir todo cambio.');

  add('arbol-nx', [
    cue('Proponemos un monorepo Nx propio del POS con aplicaciones de caja, sucursal y país, y bibliotecas por capacidad de negocio. Los contratos compartidos coordinan la evolución; cada aplicación conserva su ciclo de despliegue.', '.slide-head'),
    cue('Apps incluye cliente de escritorio, backend de sucursal, sincronizador, API de país, worker ERP y backoffice. Cada aplicación compone sus dependencias. Los workers se supervisan de manera independiente de la interfaz.', '.code-aside article:nth-child(1)'),
    cue('Las bibliotecas de ventas, caja, precios, pagos, devoluciones y fiscalidad tienen dueños y contratos. Los módulos de ERP y sincronización también conservan responsabilidades. UI reúne componentes de presentación; no debería contener credenciales de base de datos.', '.code-aside article:nth-child(2)'),
    cue('En precios, domain contiene las reglas del cálculo; application coordina cotizaciones y activaciones; infrastructure conecta PostgreSQL y la recepción de publicaciones. El módulo conserva su contrato y sus pruebas dentro del backend de sucursal.', '.code-aside article:nth-child(3)'),
    cue('Cada módulo tendrá propietario, interfaz pública y pruebas de compatibilidad. Shared kernel se limitará a conceptos mínimos como dinero e identidad. Los modelos internos de venta o ERP no se expondrán como dependencias comunes de todo el repositorio.', '.takeaway')
  ]);
  compare('reglas-de-dependencia', 'Precios y los demás módulos mantendrán sus reglas de negocio separadas de los frameworks y proveedores. La aplicación coordinará casos de uso, y la infraestructura implementará almacenamiento y conexiones a través de contratos propios.', [
    'Dominio contiene reglas y tipos del negocio. No debería importar Angular, Nest, SQL ni un SDK remoto para calcular un precio. Entradas explícitas permiten pruebas deterministas con casos conocidos.',
    'Aplicación coordina casos de uso, autorización y unidad de trabajo. Define las capacidades que necesita mediante puertos y decide qué hacer con sus resultados. No reparte esa coordinación entre botones de distintas pantallas.',
    'Infraestructura implementa persistencia y clientes técnicos, junto con la frontera del proveedor. La aplicación concreta conecta estas implementaciones. Otro módulo no debería leer libremente su ORM solo porque comparte repositorio.'
  ], 'Las reglas de importación no sustituyen permisos SQL ni controles de ejecución. Cada frontera necesita su mecanismo y su evidencia.');
  cards('limites-nx-en-ci', 'El repositorio verificará automáticamente las dependencias permitidas entre módulos. La configuración de Nx y las comprobaciones de código deben impedir que precios importe SDKs de pagos o que ventas dependa de tablas internas del ERP.', [
    'Precios recibirá sus entradas mediante contratos públicos y conservará sus reglas dentro del módulo. Los consumidores usarán esa interfaz; los detalles de pagos, persistencia e integración seguirán en sus fronteras correspondientes.',
    'Las comprobaciones automáticas de código detectan importaciones prohibidas o ciclos. Ayudan a evitar que un cambio cotidiano distribuya detalles externos por el núcleo sin advertirlo.',
    'Las pruebas de comportamiento cubrirán contratos, permisos, transacciones y recuperación. Además de compilar, cada cambio relevante deberá demostrar que conserva la confirmación durable y no habilita operaciones sin autorización.'
  ], 'Nx puede organizar y ejecutar estas verificaciones. La regla arquitectónica define qué frontera se protege; los controles automáticos detectan incumplimientos y las pruebas verifican el comportamiento esperado.');
  cards('cadena-de-verificacion', 'La aceptación del POS combinará pruebas de reglas, contratos, persistencia, recuperación y dispositivos. Cada capa debe aportar evidencia sobre los importes, permisos, estados y capacidades nacionales que protege.', [
    'Las pruebas de reglas puras cubren precios, ofertas, límites y redondeos. Usan casos de referencia para comprobar tanto el importe como la explicación de las reglas aplicadas.',
    'Las pruebas de contratos comprueban que productor y consumidor interpretan lo mismo. Incluyen variantes nacionales y proveedores, especialmente estados y unidades que podrían traducirse mal sin un error de tipos.',
    'Las pruebas de persistencia verifican restricciones, transacciones y concurrencia. Por ejemplo, que un duplicado no cree otro efecto y que versión activa y cursor nunca se publiquen por separado.',
    'Las pruebas de recuperación cortan procesos en fronteras concretas, restauran y repiten entregas. Deben mostrar qué quedó confirmado, qué es incierto y qué acción recupera sin duplicar.'
  ], 'Los componentes nativos también requieren pruebas de sistema operativo, firma y periféricos. Compartir código no demuestra compatibilidad de toda la combinación.');
  cards('versiones-y-anillos', 'La flota debe admitir versiones mixtas mientras las cajas están desconectadas. Proponemos contratos compatibles y despliegue por anillos: laboratorio, piloto y ampliación, con criterios de avance y reversión ligados a datos y pendientes.', [
    'Versionamos contratos, núcleo, perfiles, adaptadores y artefactos. Esto permite identificar qué combinación produjo un resultado y qué mensajes antiguos debe seguir entendiendo un receptor nuevo.',
    'Homologamos combinaciones reales con proveedor, SDK, sistema operativo y dispositivo cuando corresponda. Una versión instalada no demuestra por sí sola que esa combinación haya sido validada.',
    'Desplegamos por anillos: laboratorio, piloto y ampliación. Cada etapa necesita evidencia y responsables. El objetivo es detectar incompatibilidades con alcance acotado antes de afectar a toda la operación.',
    'La recuperación debe ser compatible con datos y pendientes. Revertir binarios puede ser inseguro después de una migración destructiva. Hay que demostrar lectura del esquema y recuperación de intentos previos.'
  ], 'Expandir, migrar y retirar de forma controlada permite convivencia. Una prueba automática de dispositivo tampoco debe generar cobros o documentos reales sorpresivos.');
  compare('reutilizar-plataforma', 'Proponemos reutilizar bibliotecas de core y acciones de devops-platform después de revisar sus dependencias y garantías. Las capacidades necesarias para vender sin Internet deben ejecutarse o estar disponibles en sucursal, sin una API central obligatoria por operación.', [
    'Podemos consumir bibliotecas de logs, correlación y contratos con versiones y responsables. El repositorio corporativo llamado core no es automáticamente el núcleo de negocio POS. Se adopta por capacidad compatible, no por su nombre.',
    'Las APIs corporativas pueden publicar maestros e integrar información central. Los datos necesarios para una operación offline autorizada deben estar disponibles en tienda. Una consulta remota obligatoria por cada venta rompería esa capacidad.',
    'Las acciones de entrega corporativas pueden reutilizarse fijando versiones y adaptándolas a la flota POS. Desplegar una aplicación cloud no demuestra distribución, firma, actualización y recuperación de dispositivos en sucursal.'
  ], 'La propuesta mantiene un monorepo POS con releases propios que consume piezas corporativas compatibles. La propiedad y ubicación definitivas deben acordarse explícitamente.');
  cards('observabilidad-y-recuperacion', 'La operación dispondrá de estados, métricas y trazas correlacionadas por venta, pago y entrega. Cada pendiente debe mostrar antigüedad, destino, causa y responsable, junto con una acción de recuperación autorizada.', [
    'Los pendientes se observan por cantidad, antigüedad, destino y causa. Un trabajo técnico temporal requiere otro tratamiento que un rechazo de contrato o un efecto monetario incierto.',
    'Precios debe mostrar versión activa, recibida y aplicada, junto con vigencia y validación. Así distinguimos atraso de transferencia, incompatibilidad y una publicación que ya se confirmó.',
    'Los efectos inciertos conservan identidades y referencias de pago, fiscalidad o ERP. Una consulta o conciliación resuelve lo que una respuesta perdida no permite adivinar. Los logs no deben contener tarjetas ni secretos.',
    'Restauración necesita objetivos de pérdida de datos y tiempo de recuperación según el fallo. También debe excluir al escritor anterior para que no opere simultáneamente con el restaurado bajo la misma autoridad.'
  ], 'Una cola vacía no acredita conciliación. Hay que comparar conteos, importes por moneda, referencias y día comercial, con cobertura y frescura conocidas.');
  compare('capacidad-del-backlog', 'La reconexión simultánea de sucursales requiere capacidad para las ventas nuevas y para el atraso. La plataforma limitará concurrencia y caudal por destino para recuperar pendientes sin saturar el ERP ni afectar otros países.', [
    'Medimos entradas nuevas, éxitos por destino y tamaño y antigüedad del pendiente. Contar mensajes puede ocultar lotes muy distintos; también importan registros, bytes y tiempo de servicio.',
    'Regulamos concurrencia y caudal. La espera creciente con dispersión temporal evita que todas las sucursales reintenten juntas. La admisión escalonada protege al ERP mientras se recupera.',
    'Con seiscientos trabajos pendientes, diez nuevos por minuto y treinta completados por minuto, la capacidad neta de recuperación sería de veinte por minuto: unos treinta minutos si se sostienen esas tasas. El dimensionamiento real debe medir tamaños, destinos y capacidad del proveedor.'
  ], 'Si completamos tanto como llega, el atraso no disminuye. No eliminamos obligaciones monetarias para que el contador se vea vacío; los errores necesitan resolución y trazabilidad.');
  cards('criterios-del-piloto', 'Proponemos un piloto con un corte completo de venta y un segundo perfil nacional. Debe demostrar reutilización del núcleo, adaptación de proveedores, integridad del dinero y recuperación bajo fallos controlados.', [
    'La aceptación exige identificar qué código y pruebas comparten los perfiles, qué configuración cambia y qué extensiones se incorporan. La comparación debe cubrir contratos y comportamiento, además de la experiencia de usuario.',
    'La evidencia técnica recorre una venta, caja, pago, documento, commit, entrega e integración. Incluye desconexión, duplicados, respuesta incierta, descarga parcial y restauración, conservando datos y resultados verificables.',
    'La operación gobernada define responsables, combinaciones compatibles, observabilidad y despliegue gradual. La recuperación debe poder ejecutarse de forma segura, no depender de alguien que recuerde un procedimiento improvisado.'
  ], 'La decisión de ampliar el despliegue dependerá de evidencia del piloto: perfiles nacionales reutilizables, conciliación, recuperación y compatibilidad de la flota. Esa evidencia debe revisarse con negocio, operaciones, finanzas e integración antes de operar dinero real.');

  function lab(id, opening, scenarios, ending) {
    const cues = [cue(opening, '.slide-head')];
    scenarios.forEach((steps, scenario) => steps.forEach((text, step) => cues.push({ text, lab: { scenario, step } })));
    cues.push(cue(ending, '.takeaway'));
    add(id, cues);
  }
  // Every laboratory step is narrated while that exact state is displayed.
  lab('laboratorio-venta', 'La venta ficticia es de once mil cuatrocientos pesos chilenos. Una caída de Internet permite continuar si la red local y el servidor siguen disponibles. Una respuesta de pago perdida exige resolver la incertidumbre antes de repetir el cobro. Son fallos distintos, con recuperación distinta.', [
    [
      'Primer escenario: efectivo con Internet caído. La red local y el servidor de sucursal siguen disponibles. El backend comprueba permisos, precios y capacidad fiscal de esta operación. Por eso la decisión de continuar depende de este contexto completo; no basta con que exista una copia de productos en la pantalla.',
      'Ahora fijamos identidad y cotización. La venta y el intento de pago tienen referencias propias, que conservaremos durante toda la recuperación. El backend conoce moneda y versión de precios. Si hubiera un efecto externo, su intención debe quedar persistida antes de invocarlo, para poder reconocerlo después de una caída.',
      'En este caso se registra efectivo recibido por el importe indicado. El resultado es conocido bajo esa modalidad. No extrapolamos el ejemplo a tarjeta: un pago con proveedor necesita evidencia y una capacidad autorizada. Tener precios locales no permite declarar aprobado un cargo bancario sin respuesta.',
      'Este es el punto de confirmación local. PostgreSQL guarda venta, líneas, pago, movimiento, auditoría y pendiente de salida en el mismo commit. La venta está confirmada y ERP permanece pendiente. Son estados compatibles: la operación local existe, pero su integración posterior todavía no terminó.',
      'Después del commit respondemos a la cajera y entregamos el documento permitido. Si falla la impresora, recuperamos o reimprimimos la misma referencia; no repetimos la venta. La impresión es una consecuencia visible, pero no reemplaza la evidencia durable que ya quedó en la base.',
      'Vuelve Internet y el worker entrega el evento original. País acredita recepción durable, mientras el ERP sigue en proceso. La sucursal no vuelve a confirmar otra venta ni cobrar otra vez. La recuperación completa una etapa pendiente de la operación que ya tenía identidad y resultado local.'
    ], [
      'Segundo escenario: pago con resultado incierto. Antes de cobrar persistimos el intento, su proveedor, cuenta, dispositivo y perfil. Estas referencias permiten preguntar por la misma operación. Guardar únicamente un error después de la llamada sería insuficiente si el proceso cae sin recordar qué intentó hacer.',
      'El adaptador envía el comando al destino asignado y espera evidencia. Este escenario supone conectividad y una modalidad de pago autorizada. No es un ejemplo de tarjeta offline. El importe y la identidad proceden del flujo aprobado; el dispositivo no crea otro intento por su cuenta.',
      'La respuesta no llega a tiempo. El proveedor pudo cobrar, así que conservamos resultado desconocido y bloqueamos un nuevo cobro a ciegas. No lo marcamos como rechazado para facilitar otro intento. El estado representa exactamente lo que sabemos: todavía falta evidencia concluyente.',
      'Consultamos la misma operación en el proveedor original si su contrato ofrece esa capacidad. Si la consulta no resuelve, queda conciliación o intervención trazable. Cambiar de dispositivo no elimina la incertidumbre; necesitamos responder qué ocurrió con el intento que ya pudo afectar dinero.',
      'En este caso, la consulta confirma autorización y devuelve la referencia original. Conservamos esa evidencia para continuar o recuperar. La liquidación sigue siendo otro estado. Si ahora falla la venta local, debemos resolver desde el intento conocido, no volver a cargar la tarjeta para empezar de cero.',
      'Finalmente el commit local conserva venta, referencia del pago, auditoría y outbox. La operación lógica de cobro sigue siendo una, aunque hubo consulta y recuperación. La contabilización ERP permanece pendiente. Distinguir cada evidencia permite continuar con honestidad sin convertir un fallo de comunicación en un duplicado monetario.'
    ]
  ], 'En ambos recorridos la identidad y la evidencia sobreviven a la pantalla y a los reintentos. La venta local, la recepción en país y el resultado ERP conservan estados separados.');
  lab('laboratorio-eventos-precios', 'Un cambio válido, una entrega repetida y un hueco en la secuencia necesitan tratamientos distintos. El evento recibido no modifica directamente las filas que usa una venta: construye una candidata, comprueba su cobertura y solo después puede publicarla.', [
    [
      'Primer escenario: cambio válido. La fuente de país aprueba la versión cuarenta y dos para la entidad indicada, partiendo de la cuarenta y uno. Manifiesto y evento de salida quedan juntos. La autorización nace en esa fuente; la sucursal recibirá una publicación identificada, no una instrucción anónima de cambiar un importe.',
      'La sucursal recibe identidad, secuencia y huella, y guarda la recepción de forma durable. La sucursal recibió cuarenta y dos, pero sigue aplicada y activa la cuarenta y uno. Acusar recepción permite al emisor conocer esa etapa; todavía no permite afirmar que una venta puede usar los nuevos precios.',
      'El cambio se aplica sobre una copia aislada de la versión anterior. Mientras construimos la candidata, la activa conserva su precio de doce mil pesos. Así ninguna venta combina media actualización de promociones con precios anteriores. Preparar no significa editar en sitio los datos publicados.',
      'La candidata pasa la validación completa. Se comprueban procedencia, bytes, cobertura, referencias, moneda, compatibilidad y vigencia. Un delta ahorra transferencia, pero no salta este control. La aprobación debe corresponder al conjunto resultante y al motor que realmente lo calculará.',
      'Ahora se publica con un commit corto. La base todavía debe ser la esperada; entonces cambian juntos el puntero activo, la inbox aplicada y el cursor. La nueva versión muestra once mil cuatrocientos pesos. Si falla la transacción, no declaramos progreso parcial ni dejamos el puntero adelantado.',
      'Las cotizaciones nuevas utilizan la versión cuarenta y dos. Las que estaban abiertas conservan su explicación anterior y revalidan al confirmar según política. Una venta confirmada no se recalcula por esta publicación. El cambio de catálogo no debe modificar silenciosamente historia ni acuerdos que necesitan nueva aceptación.'
    ], [
      'Segundo escenario: el acuse se perdió después de activar. La fuente reenvía el mismo evento con igual contenido. Eso no es necesariamente un fallo del emisor: desde su perspectiva no recibió la confirmación. El receptor debe estar preparado para reconocer una entrega repetida.',
      'La inbox compara identidad dentro del origen y consumidor correctos, además de la huella del contenido. Ambas coinciden con una operación ya aplicada. Si el identificador coincidiera pero los datos fueran distintos, sería un conflicto, no una actualización que deba aceptarse silenciosamente.',
      'Como reconoce el resultado anterior, no reconstruye ni aplica otra vez. La versión, el número de aplicaciones y el cursor permanecen iguales. Esta es la protección del efecto local: el transporte pudo repetir, pero no duplicó descuentos ni creó otro avance artificial.',
      'El acuse llega finalmente a la fuente y cierra esa entrega. El resultado conservado permite responder con evidencia. No borramos todo el historial inmediatamente: la retención debe soportar recuperación, conciliación y posibles repeticiones dentro del horizonte acordado.'
    ], [
      'Tercer escenario: llega cuarenta y tres antes que cuarenta y dos. La activa sigue en cuarenta y uno y el cambio nuevo requiere otra base. Un número mayor no prueba que tengamos todas las modificaciones intermedias, incluidas bajas y condiciones que podrían afectar al cálculo.',
      'Guardamos lo recibido en preparación y lo dejamos pendiente. El cursor aplicado permanece en cuarenta y uno. Esta separación conserva progreso de transferencia sin exponer una promoción parcial a la venta. Recibimos algo útil para recuperar, pero todavía no tenemos una versión publicable.',
      'El worker pide repetir desde el último punto completo. Si la fuente ya no conserva el tramo, solicita una fotografía consistente nueva. El protocolo debe definir ese límite de retención; no suponemos que cualquier evento histórico estará disponible para siempre.',
      'Llegó el cambio faltante. Reconstruimos cuarenta y dos y cuarenta y tres en orden sobre la candidata, incluidas eliminaciones, y validamos el conjunto. Lo importante no es haber recibido dos mensajes, sino demostrar que la base y sus cambios forman una versión completa.',
      'Con precondiciones vigentes, un commit publica cuarenta y tres y su progreso. Durante la espera, la versión anterior solo podía servir dentro de su autorización. Si hubiera vencido, se restringía el cálculo afectado; esperar un hueco no concede vigencia adicional.'
    ]
  ], 'Duplicado y hueco son situaciones distintas. El duplicado recupera un resultado conocido; el hueco exige recuperar cobertura antes de publicar. Ninguno justifica parchear filas de la versión activa.');
  lab('laboratorio-snapshot-precios', 'Una carga masiva incorpora la fotografía completa de un ámbito. Debe recuperar descargas incompletas, rechazar datos inválidos y coordinar publicaciones concurrentes. El objetivo es incorporar datos sin perder cambios nuevos ni retroceder una versión que ya avanzó.', [
    [
      'Primer escenario: carga completa con cambios concurrentes. Una agenda o una acción manual crea trabajo autorizado y durable. Ambas usan límites y auditoría iguales. La activa sigue en cuarenta y uno mientras la preparación comienza; el disparador no publica por sí mismo.',
      'El origen declara un corte consistente llamado H, con valor cien en el ejemplo. La fotografía contiene los cambios de su ámbito hasta ese punto, incluidas bajas. Este corte permite saber qué cambios posteriores debemos recuperar; la hora del computador no ofrece esa garantía.',
      'Los bloques se descargan a un área aislada y se guarda progreso. Mientras tanto aparecen los cambios ciento uno y ciento dos, que se retienen para completar la foto. La versión activa sigue atendiendo y no mantenemos una transacción SQL abierta durante toda la transferencia.',
      'Comparamos los bytes con la huella del manifiesto y alcanzamos el flujo aplicando los cambios posteriores al corte. Este avance, o catch-up, evita perder modificaciones que ocurrieron durante la descarga. Una foto correcta en cien podría quedar incompleta respecto del punto final si ignoramos esos cambios.',
      'Validamos la candidata resultante, no solo cada archivo. Comprobamos referencias, bajas, cobertura, esquema, motor y vigencia, y la dejamos inmutable. Una fotografía descargada y cambios individuales correctos todavía necesitan formar un conjunto coherente antes de exponerse al cálculo.',
      'El cambio final compara la versión actual con la esperada. Solo si sigue siendo compatible publica el nuevo puntero, inbox aplicada y checkpoint juntos. La sigla CAS resume cambiar si coincide. Impide que una preparación basada en información antigua sobrescriba sin comprobar el estado real.',
      'Las nuevas cotizaciones leen la versión publicada. Las abiertas mantienen su referencia y revalidan según política. Retenemos versiones necesarias para explicar operaciones en curso e históricas; limpiar almacenamiento no puede borrar una versión que todavía necesita el negocio o la recuperación.'
    ], [
      'Segundo escenario: descarga incompleta o inválida. Llegaron dos de tres bloques. La activa y el cursor aplicado siguen en cuarenta y uno. Tener filas nuevas en disco no permite tratarlas como catálogo terminado ni completar la parte faltante con datos arbitrarios.',
      'Al volver la conexión, el trabajo conserva identidad y solicita lo pendiente contra el mismo manifiesto. El progreso durable evita reiniciar sin necesidad y permite comprobar exactamente qué falta. La recuperación sigue separada de las lecturas de venta.',
      'Ahora la huella no coincide. Los bytes no corresponden a la publicación esperada, así que bloqueamos la candidata y guardamos evidencia. No avanza el cursor aplicado. Un error de copia no se arregla aceptándolo manualmente como si fuera una versión válida.',
      'La anterior permanece íntegra, pero solo puede usarse mientras continúe autorizada. No renovamos su vigencia para ocultar el problema de descarga. Si vence, la política restringe el cálculo correspondiente hasta recuperar datos autorizados o aplicar la alternativa aprobada.',
      'El operador ve trabajo, versión y motivo del fallo. Corrige la causa y vuelve a pasar por descarga, validación y activación. El mismo proceso permite auditar la recuperación. Un botón manual no es una vía de escape para forzar datos inválidos.'
    ], [
      'Tercer escenario: una carga lenta partió de cuarenta y uno y prepara una candidata hasta cien. Durante la descarga no bloqueamos todas las ventas ni asumimos que nadie más podrá publicar. Por eso conservamos la base esperada como precondición, no como certeza permanente.',
      'Otro trabajo válido completó cambios más nuevos y publicó ciento cinco. La activa y el cursor aplicado avanzaron mientras la carga lenta seguía preparando cien. Ambas tareas tuvieron progreso, pero no podemos publicar la más antigua ignorando el nuevo estado.',
      'La comparación final detecta que la activa ya no coincide con cuarenta y uno. La transacción se aborta y evita sobrescribir ciento cinco con cien. Rechazar esta publicación no es perder trabajo arbitrariamente: protege un avance que ya estaba confirmado.',
      'Para recuperar, releemos el estado y reconstruimos con una base compatible y el historial retenido. Si falta ese historial, pedimos otra fotografía. No basta cambiar el valor esperado para que la comparación pase; la candidata tiene que representar el conjunto correcto.',
      'También revalidamos el tiempo. Una candidata pudo ser válida al descargar y vencer antes de activar. El commit comprueba autorización actual con política de reloj; ni el checksum correcto ni la espera en cola extienden su vigencia.'
    ]
  ], 'Una carga masiva segura combina corte consistente, progreso recuperable, cambios posteriores, validación y publicación condicionada. La operación de venta no debe leer datos parciales ni retroceder por una carrera entre trabajos.');
  lab('laboratorio-entrega', 'Una entrega durable conserva el pendiente aunque se pierda la respuesta o el trabajo requiera cuarentena. El resultado guardado en país puede diferir de lo que alcanzó a conocer la sucursal. Repetir el transporte puede ser necesario; repetir el efecto local no.', [
    [
      'Primer escenario: el acuse se pierde. El worker reclama un evento de venta ya confirmado en la outbox de sucursal. País recibe una copia del hecho, pero no se convierte en un segundo autor libre de modificar esa venta. La entrega todavía está pendiente en origen.',
      'País valida autorización, ámbito, contrato e identidad antes de aplicar. Una restricción única protege origen, consumidor y evento; la huella permite reconocer el mismo contenido. Reutilizar el identificador con otro contenido debe producir conflicto, no sobrescribir el registro anterior.',
      'País confirma juntos inbox aplicada, proyección local y trabajo posterior para ERP. Ahora existe un efecto durable y exactamente ese trabajo pendiente bajo las protecciones del ejemplo. Todavía no salió el acuse: guardar y avisar son acciones separadas.',
      'La respuesta se pierde después del commit. Desde sucursal falta evidencia, así que el evento sigue pendiente y se reenvía con la misma identidad, espera creciente y dispersión. No inferimos fracaso del receptor solo porque el emisor agotó su espera.',
      'País reconoce identidad y huella ya aplicadas. Devuelve el resultado previo sin otra proyección ni otro trabajo ERP. Los contadores permanecen en uno. La garantía proviene de restricciones y transacción, no de esperar que la red nunca repita.',
      'Finalmente sucursal marca entrega confirmada. ERP todavía está pendiente en país. El acuse acredita esa frontera, no toda la cadena. Retención y restauración deben conservar o reconstruir el recuerdo necesario para reconocer futuros reenvíos.'
    ], [
      'Segundo escenario: un fallo temporal y después una incompatibilidad. El destino no está disponible, así que el trabajo conserva identidad, error y próximo intento. No se pierde por salir de la memoria del worker y tampoco se presenta como entregado.',
      'Aplicamos espera creciente y dispersión, llamada jitter, además de límites de concurrencia. Esto reduce reintentos simultáneos que podrían empeorar la caída. La identidad del evento no cambia porque haya cambiado el momento de volver a intentar.',
      'El destino vuelve, pero rechaza el contrato. Reenviar indefinidamente los mismos bytes no modifica esa incompatibilidad. El trabajo pasa a cuarentena con causa y responsable, manteniendo visible que el negocio no completó esa entrega.',
      'Otros ámbitos independientes pueden continuar. Si un evento posterior depende del que falló, conservamos el hueco y detenemos esa aplicación. Aislar el error no significa fingir que la dependencia desapareció ni adelantar progreso sobre un hecho ausente.',
      'Después de corregir la incompatibilidad, una acción autorizada reejecuta con la identidad original. Si lo que cambia es el hecho de negocio, se crea una corrección relacionada, no se muta el evento original. Así la auditoría puede explicar qué se intentó y por qué.'
    ]
  ], 'Entrega al menos una vez e idempotencia local son garantías acotadas. No prometen exactamente una vez en todos los proveedores ni eliminan la necesidad de conciliación.');
  lab('laboratorio-bullmq', 'Para preparar publicaciones de precios en país, BullMQ es una opción de coordinación sobre Redis. La venta local conserva independencia de esa cola. PostgreSQL registra la operación, su intención de encolado y el resultado que debe sobrevivir a los reintentos.', [
    [
      'Primer escenario: preparar una fotografía de precios. País registra el trabajo y su intención de encolado a partir de una agenda o petición autorizada. La venta local sigue independiente. Programar un job no significa que el resultado ya exista ni que vaya a comenzar exactamente a esa hora.',
      'El publicador añade el trabajo con identidad estable y una política acotada de intentos y espera. Estos parámetros se acuerdan según la responsabilidad. El identificador ayuda a coordinar la cola, pero la protección permanente del efecto no debe depender solo de que el job siga guardado allí.',
      'El worker comprueba la operación durable antes de producir algo. Si ya está terminada, recupera el resultado; si no, reclama su ejecución con exclusión y recuperación. Los registros del negocio no viven únicamente en Redis ni desaparecen cuando se limpia un job.',
      'El worker prepara el paquete desde un corte consistente, calcula la huella y valida cobertura. Todavía no publica filas incompletas. El archivo que se apruebe debe ser inmutable para que lo validado corresponda exactamente a lo que descargarán las sucursales.',
      'PostgreSQL confirma manifiesto aprobado, operación terminada y outbox de notificación juntos. La clave de negocio protege contra publicar dos resultados para el mismo trabajo. Una caída después de este punto debe poder recuperar esta evidencia, aunque la cola todavía no conozca el éxito.',
      'El worker retorna y BullMQ marca completado. Eso significa que terminó este job de preparación. Las tiendas aún deben descargar, validar y activar. Una tarea central completada no demuestra que toda la flota tenga ya la nueva versión.'
    ], [
      'Segundo escenario: el proceso cae después del commit. La publicación quedó confirmada en PostgreSQL, pero BullMQ no recibió la finalización. Base y cola no comparten una transacción automática. Sus estados pueden diferir sin que eso borre el resultado comercial ya persistido.',
      'La recuperación de la cola puede volver a entregar el job interrumpido. Esto es una ejecución repetida, no necesariamente otra publicación. El ID del job ayuda en la coordinación, pero no garantiza que una función se ejecute una sola vez en toda situación de caída.',
      'La base reconoce la operación terminada y recupera el manifiesto anterior. No construye otra publicación ni otra notificación. Esta comprobación permite que dos ejecuciones del worker correspondan a un único efecto de negocio protegido y a un resultado que podemos explicar.',
      'El worker devuelve el resultado recuperado y ahora la cola registra completado. El transporte se puso al día con la evidencia del negocio. El número de publicaciones sigue en uno porque la protección estaba en la identidad y persistencia de la operación, no en la esperanza de no repetir.'
    ], [
      'Tercer escenario: se agotan intentos. La fuente falla antes de publicar el paquete. Un fallo temporal puede reintentarse con evidencia; una entrada inválida necesita corrección. No todos los errores se resuelven esperando ni todos justifican repetir un efecto remoto incierto.',
      'La cola programa intentos con espera creciente y límites. En cada ejecución el worker vuelve a consultar la operación durable antes de producir resultado. No supone que el intento anterior no hizo nada solo porque el job aún figure pendiente o fallido.',
      'Al agotar la política, el trabajo queda fallido con error y responsable. La obligación no desaparece. PostgreSQL conserva evidencia aunque una política de retención elimine después la fila del job en la cola. El operador necesita saber qué resolver y con qué alcance.',
      'Corregida la dependencia, una acción autorizada reejecuta la misma operación de negocio y audita esa decisión. La base vuelve a comprobar si ya existe resultado. El mecanismo de reactivar un job no sustituye la idempotencia y recuperación del efecto que representa.'
    ]
  ], 'BullMQ coordina ejecución. La aplicación conserva significado, autorización y evidencia. Separar ambas responsabilidades permite recuperar trabajos sin convertir un reintento técnico en otra publicación comercial.');
  lab('laboratorio-rabbitmq', 'Para distribuir ventas confirmadas a ERP y analítica, RabbitMQ es una opción con colas separadas por consumidor. La outbox conserva mensajes sin ruta. La confirmación del broker y el acuse del consumidor se registran como etapas diferentes.', [
    [
      'Primer escenario: país tiene un evento confirmado y dos destinos interesados, ERP y analítica. RabbitMQ es una opción de distribución en país. El hecho sigue teniendo como autora a la sucursal y el broker permanece fuera del commit original de la venta.',
      'La publicación utiliza persistencia, topología durable y confirmaciones según la configuración probada. También controla mensajes sin ruta. Un publisher confirm indica la responsabilidad asumida por el broker; no demuestra que el ERP haya registrado la operación ni que analítica esté actualizada.',
      'El exchange distribuye copias a dos colas vinculadas. Así cada consumidor lógico recibe el evento. Si ERP y analítica compartieran una sola cola, competirían por mensajes: no recibirían necesariamente ambos cada hecho. Colas distintas permiten progreso y recuperación independientes.',
      'Analítica confirma inbox y proyección en su propia base, junto con trabajo posterior si corresponde. Solo después envía el ACK de consumidor. Si cae antes del acuse, la entrega puede repetirse y se reconoce por identidad y contenido sin duplicar su efecto local.',
      'El consumidor de integración guarda inbox y trabajo ERP antes de acusar. La llamada externa ocurre después y necesita sus propias garantías. El commit local no incluye la escritura en el ERP remoto; su resultado y recuperación se conservan por separado.',
      'Analítica puede quedar al día mientras ERP está caído. Colas y recursos separados permiten aislar ese atraso, pero cada destino necesita métricas, retención y responsable. Que una cola esté vacía no dice que todos los consumidores ni todos los efectos externos hayan terminado.'
    ], [
      'Segundo escenario: la publicación no coincide con ninguna cola vinculada. El broker puede recibir el mensaje sin entregarlo al destino esperado. Por eso no basta tratar cualquier confirmación como éxito de toda la ruta. La outbox conserva la obligación de entregar.',
      'La opción mandatory permite recibir la devolución de un mensaje sin ruta. El publicador procesa devoluciones y errores además del confirm, porque un mensaje devuelto también puede recibir confirmación del broker. La outbox continúa pendiente; la publicación todavía no acredita una entrega exitosa.',
      'La revisión corrige la vinculación faltante y reenvía el mismo evento. El ID estable permite que el consumidor proteja su efecto si existió ambigüedad o alguna entrega repetida. Corregir topología no requiere convertir el hecho en otro evento diferente.',
      'Ahora un consumidor encuentra un fallo temporal. Aplicamos una ruta de reintentos con espera y límite. Reencolar inmediatamente en un bucle puede consumir capacidad y agravar el fallo sin darle tiempo a la dependencia para recuperarse.',
      'Al agotarse la política o aparecer un error permanente, el mensaje queda en una cola de cuarentena con causa y responsable. Dead letter no significa reparado ni confirmado. La ruta de cuarentena también debe configurarse y probarse; el nombre de la cola no aporta esa garantía.',
      'Se resuelve la causa y un replay autorizado mantiene la identidad original. El consumidor confirma su efecto local antes de acusar. Si el resultado remoto es incierto, consulta o concilia: un replay técnico no autoriza repetir ciegamente una operación monetaria.'
    ]
  ], 'El confirm del broker y el ACK del consumidor tienen alcances diferentes. La arquitectura conserva un pendiente y una evidencia en cada frontera, en lugar de una etiqueta genérica de sincronizado.');
  lab('laboratorio-frontera-erp', 'La venta ficticia V cuarenta y dos, por doce mil novecientos pesos, se integra mediante fachada, ACL y adaptador. Ya está confirmada localmente: aquí no volvemos a cobrar. Los dos escenarios son alternativas de respuesta del ERP demo, no dos envíos que debamos realizar para la misma venta.', [
    [
      'Primer escenario: recibido, todavía pendiente de seguimiento. El worker solicita registrar la venta con identidad del POS y cliente C diecisiete. Su responsabilidad es gestionar el trabajo pendiente; no necesita construir campos ni interpretar códigos particulares del ERP para pedir la capacidad.',
      'La llamada llega a la fachada. Ofrece una entrada estable y coordina la frontera asignada. El consumidor no debe saber qué traducción y adaptador participan por dentro. Esta comodidad no reemplaza autorización, intención durable ni recuperación: esas garantías pertenecen al flujo completo.',
      'La ACL prepara las equivalencias. El cliente C diecisiete corresponde a la cuenta A novecientos uno del ERP ficticio. No es solo cambiar el nombre customer por account: necesitamos una relación validada para esa entidad y destino. Una equivalencia ausente debe tratarse como problema, no inventarse.',
      'El adaptador realiza la llamada HTTP al destino. Conoce URL, protocolo y detalles técnicos; no decide reglas de precios. En este momento sigue esperando evidencia. Enviar correctamente una solicitud todavía no demuestra que el ERP haya registrado la venta.',
      'Llega una respuesta HTTP satisfactoria con el código de recibido. El adaptador conserva esa evidencia. Aún hace falta interpretarla según el contrato del ERP demo: el código de transporte por sí solo no transforma la operación en contabilizada.',
      'La ACL interpreta recibido para procesar y devuelve el estado propio recibido. El registro sigue pendiente y necesita seguimiento. Esta traducción protege a los consumidores: ninguna pantalla debería asumir que un HTTP satisfactorio significa una integración finalizada.',
      'La fachada devuelve ese resultado en el contrato POS. El worker decide el seguimiento sin interpretar códigos del proveedor. Si el ERP cambia una etiqueta conservando el mismo significado, se actualiza la equivalencia y sus pruebas dentro de la integración.',
      'El worker guarda el estado recibido y programa la consulta acordada. La venta local permanece confirmada y no se vuelve a cobrar. Lo pendiente es conocer el registro externo; el trabajo y la referencia conservados permiten continuar sin confundir esa espera con fracaso de la venta.'
    ], [
      'Segundo escenario alternativo: el proveedor acreditará registrado. Empezamos desde el mismo ejemplo para comparar respuestas, no para enviar otra vez una venta real. El worker sigue usando la capacidad propia del POS con la misma forma de datos, sin conocer las convenciones del ERP.',
      'La fachada vuelve a coordinar la frontera seleccionada. Su interfaz no cambia porque el resultado remoto vaya a ser distinto. La responsabilidad es ofrecer una capacidad estable y devolver estados honestos, no ocultar todas las diferencias bajo un booleano de éxito.',
      'La ACL utiliza las mismas equivalencias validadas de cliente, importe y contexto. El consumidor permanece independiente de la cuenta A novecientos uno. Si esta equivalencia fuera incorrecta, una llamada HTTP técnicamente exitosa podría registrar la operación en la cuenta equivocada.',
      'El adaptador envía por el protocolo acordado y conserva errores o evidencia. La llamada remota es un límite de fallo: podría completarse sin que la respuesta llegue. Este escenario recibirá respuesta, pero el flujo productivo también debe tratar la incertidumbre.',
      'El ERP demo devuelve ahora el código BOOKED con HTTP satisfactorio. El adaptador no lo transforma solo por intuición en liquidado o emitido fiscalmente. Conserva el resultado para la capa que conoce su significado contractual.',
      'En este contrato ficticio, BOOKED significa registrado. La ACL devuelve registrado y mantiene la referencia externa como evidencia. Esta equivalencia pertenece al ejemplo y no afirma que AX u otro proveedor real use ese código con igual significado.',
      'La fachada entrega al worker el resultado propio registrado. El consumidor sigue sin interpretar vocabulario del proveedor. La diferencia entre ambos escenarios está en la evidencia y su traducción, no en cambiar las reglas de la venta local.',
      'El worker persiste registrado con su evidencia. Eso acredita esta integración bajo el contrato demo. No afirma liquidación del pago ni emisión fiscal, que conservan otros estados. El recorrido permite ubicar cada responsabilidad sin confundir coordinación, traducción y llamada técnica.'
    ]
  ], 'El worker usa una entrada estable, la ACL traduce al modelo POS y el adaptador ejecuta el protocolo del ERP. La aplicación conserva intención, resultado y recuperación. La transacción de PostgreSQL no incluye el efecto remoto.');

  window.POS_REVEAL_NARRATION_CONTENT = content;
})();
